import json,pathlib

def inspect_swap(production,staging,required_connection_strings):
    production=json.loads(pathlib.Path(production).read_text(encoding="utf8"))
    staging=json.loads(pathlib.Path(staging).read_text(encoding="utf8"))
    def entries(doc):
        props=doc.get("properties",{})
        return {x["name"]:x for x in props.get("connectionStrings",[])}
    prod=entries(production);stage=entries(staging)
    issues=[];checked=[]
    for name in required_connection_strings:
        if name not in prod or name not in stage:
            issues.append({"name":name,"reason":"missing_from_one_slot"});continue
        p=prod[name];s=stage[name]
        if p.get("type")!=s.get("type"):
            issues.append({"name":name,"reason":"type_mismatch"});continue
        checked.append(name)
        if p.get("slotSetting") is not True or s.get("slotSetting") is not True:
            issues.append({"name":name,"reason":"not_sticky_in_both_slots"})
    return {"safe":not issues,"checked":checked,"issues":issues,
        "action":"mark required environment-specific connection strings as slot settings in both slots, then verify effective production and staging targets before and after swap; do not swap until clean"}
